def transform(grid):
    h, w = len(grid), len(grid[0])

    # The left pattern is separated from the colored shapes by an all-zero column.
    sep = next(c for c in range(w) if all(grid[r][c] == 0 for r in range(h)))
    left_w = sep
    bg = grid[0][0]

    # Record each colored shape on the right, normalized to its bounding box.
    shapes = {}
    for color in set(grid[r][c] for r in range(h) for c in range(sep + 1, w)):
        if color == 0:
            continue
        cells = [(r, c) for r in range(h) for c in range(sep + 1, w)
                 if grid[r][c] == color]
        if cells:
            min_r = min(r for r, c in cells)
            min_c = min(c for r, c in cells)
            shapes[color] = {(r - min_r, c - min_c) for r, c in cells}

    out = [row[:left_w] for row in grid]

    # Each all-background row separates one pattern panel from the next.
    r = 0
    while r < h:
        if all(out[r][c] == bg for c in range(left_w)):
            r += 1
            continue

        start = r
        while r < h and not all(out[r][c] == bg for c in range(left_w)):
            r += 1
        cells = [(rr - start, c) for rr in range(start, r)
                 for c in range(left_w) if out[rr][c] != bg]
        if not cells:
            continue

        min_r = min(rr for rr, c in cells)
        min_c = min(c for rr, c in cells)
        pattern = {(rr - min_r, c - min_c) for rr, c in cells}

        color = next((color for color, shape in shapes.items()
                      if shape == pattern), None)
        if color is not None:
            for rr in range(start, r):
                for c in range(left_w):
                    if out[rr][c] != bg:
                        out[rr][c] = color

    return out
